typedef unsigned int mmask_t;
typedef chtype attr_t;

/* WINDOW structure (opaque) */
typedef struct _win_st WINDOW;

/* Boolean */
typedef unsigned char bool;
#define TRUE 1
#define FALSE 0

/* Error codes */
#define OK 0
#define ERR (-1)

/* Key definitions */
#define KEY_DOWN 0402
#define KEY_UP   0403
#define KEY_LEFT 0404
#define KEY_RIGHT 0405
#define KEY_HOME 0406
#define KEY_F(n) (0410 + (n))
#define KEY_BACKSPACE 0407
#define KEY_ENTER 0527
#define KEY_RESIZE 0632
#define KEY_MOUSE 0631

/* Attribute definitions */
#define WA_NORMAL 0
#define WA_STANDOUT (1L << 8)
#define WA_UNDERLINE (1L << 9)
#define WA_REVERSE (1L << 10)
#define WA_BLINK (1L << 11)
#define WA_DIM (1L << 12)
#define WA_BOLD (1L << 13)
#define WA_ALTCHARSET (1L << 14)
#define WA_INVIS (1L << 15)
#define WA_PROTECT (1L << 16)

/* Legacy attribute definitions */
#define A_NORMAL WA_NORMAL
#define A_STANDOUT WA_STANDOUT
#define A_UNDERLINE WA_UNDERLINE
#define A_REVERSE WA_REVERSE
#define A_BLINK WA_BLINK
#define A_DIM WA_DIM
#define A_BOLD WA_BOLD
#define A_ALTCHARSET WA_ALTCHARSET
#define A_INVIS WA_INVIS
#define A_PROTECT WA_PROTECT
#define A_COLOR 0xff0000L

/* Color constants */
#define COLOR_BLACK 0
#define COLOR_RED 1
#define COLOR_GREEN 2
#define COLOR_YELLOW 3
#define COLOR_BLUE 4
#define COLOR_MAGENTA 5
#define COLOR_CYAN 6
#define COLOR_WHITE 7

/* COLOR_PAIR macro - defined as function call */
extern chtype COLOR_PAIR(int);

/* Global variables */
extern WINDOW *stdscr;
extern WINDOW *curscr;
extern int LINES;
extern int COLS;
extern int COLORS;
extern int COLOR_PAIRS;
extern int ESCDELAY;
extern int TABSIZE;

/* Function declarations */
extern WINDOW *initscr(void);
extern int endwin(void);
extern bool isendwin(void);

extern int cbreak(void);
extern int nocbreak(void);
extern int echo(void);
extern int noecho(void);
extern int raw(void);
extern int noraw(void);
extern int nl(void);
extern int nonl(void);

extern int intrflush(WINDOW*, bool);
extern int keypad(WINDOW*, bool);
extern int nodelay(WINDOW*, bool);
extern int notimeout(WINDOW*, bool);
extern void timeout(int);
extern void wtimeout(WINDOW*, int);

extern int curs_set(int);
extern int start_color(void);
extern int use_default_colors(void);
extern int init_pair(short, short, short);
extern int init_color(short, short, short, short);
extern bool has_colors(void);
extern bool can_change_color(void);

extern int clear(void);
extern int clrtobot(void);
extern int clrtoeol(void);
extern int erase(void);
extern int wclear(WINDOW*);
extern int werase(WINDOW*);

extern int addch(chtype);
extern int addstr(const char*);
extern int addnstr(const char*, int);
extern int mvaddch(int, int, chtype);
extern int mvaddstr(int, int, const char*);
extern int mvaddnstr(int, int, const char*, int);

extern int waddch(WINDOW*, chtype);
extern int waddstr(WINDOW*, const char*);
extern int mvwaddch(WINDOW*, int, int, chtype);
extern int mvwaddstr(WINDOW*, int, int, const char*);

extern int attron(int);
extern int attroff(int);
extern int attrset(int);
extern int wattron(WINDOW*, int);
extern int wattroff(WINDOW*, int);
extern int wattrset(WINDOW*, int);

extern int move(int, int);
extern int wmove(WINDOW*, int, int);

extern int refresh(void);
extern int wrefresh(WINDOW*);
extern int doupdate(void);

extern int getch(void);
extern int wgetch(WINDOW*);
extern int ungetch(int);

extern int beep(void);
extern int flash(void);

extern int printw(const char*, ...);
extern int mvprintw(int, int, const char*, ...);
extern int wprintw(WINDOW*, const char*, ...);

/* Macros for convenience */
#define standout() attron(A_STANDOUT)
#define standend() attrset(A_NORMAL)

EOF

