/* Character set: ASCII 0x21 ('!') to 0x7A ('z') */
#define CHAR_MIN 0x21
#define CHAR_MAX 0x7A
#define CHAR_COUNT (CHAR_MAX - CHAR_MIN + 1)

/* Japanese characters: Katakana range */
#define KANA_MIN 0x30A1
#define KANA_MAX 0x30F6

/* Color pair numbers */
#define PAIR_GREEN   1
#define PAIR_RED     2
#define PAIR_BLUE    3
#define PAIR_WHITE   4
#define PAIR_YELLOW  5
#define PAIR_CYAN    6
#define PAIR_MAGENTA 7
#define PAIR_BLACK   8

/* Options struct */
typedef struct {
    int async_mode;     /* -a: asynchronous scroll */
    int bold_some;      /* -b: some bold */
    int bold_all;       /* -B: all bold */
    int no_bold;        /* -n: no bold */
    int force;          /* -f: force linux term */
    int linux_mode;     /* -l: linux mode */
    int old_style;      /* -o: old style scroll */
    int japanese;       /* -c: japanese chars */
    int locked;         /* -L: lock mode */
    int rainbow;        /* -r: rainbow mode */
    int kinetic;        /* -k: kinetic chars */
    int screensaver;    /* -s: screensaver mode */
    int lambda;         /* -m: lambda mode */
    int xwindow;        /* -x: xwindow mode */
    int shadow_only;    /* -c: shadow only (alternate) */
    int color_pair;     /* current color pair */
    int delay;          /* -u: update delay */
    char *message;      /* -M: message to display */
    char *tty;          /* -t: tty to use */
} Options;

/* Per-column state */
typedef struct {
    int length;     /* stream length */
    int pos;        /* current head position (row, can be negative) */
    int space;      /* space before next stream */
    char *chars;    /* per-row characters */
    int timer;      /* async timer */
    int bold_flag;  /* per-row bold flags (bitmask) */
} Column;

/* Global state */
static Column *columns = NULL;
static int num_cols = 0;
static int num_lines = 0;
static Options opts;
static volatile int need_resize = 0;

/* Signal handler for SIGWINCH */
static void handle_resize(int sig) {
    (void)sig;
    need_resize = 1;
}

/* Signal handler for SIGINT */
static void handle_sigint(int sig) {
    (void)sig;
    endwin();
    exit(0);
}

/* Get a random character */
static char get_rand_char(void) {
    if (opts.lambda) {
        return 'L'; /* Lambda - use L as placeholder for ASCII */
    }
    return (char)(CHAR_MIN + rand() % CHAR_COUNT);
}

/* Get a random wide character (for Japanese mode - returns code point) */
static int get_rand_wchar(void) {
    return KANA_MIN + rand() % (KANA_MAX - KANA_MIN + 1);
}

/* Initialize column state */
static void init_column(int col) {
    Column *c = &columns[col];
    c->length = 3 + rand() % (num_lines - 2);
    c->pos = -(rand() % num_lines);  /* Start above screen at random position */
    c->space = 1 + rand() % num_lines;
    c->timer = opts.async_mode ? rand() % 5 : 0;

    if (c->chars == NULL) {
        c->chars = (char*)malloc(num_lines * sizeof(char));
    }
    memset(c->chars, ' ', num_lines);
}

/* Free column memory */
static void free_columns(void) {
    if (columns) {
        for (int i = 0; i < num_cols; i++) {
            if (columns[i].chars) {
                free(columns[i].chars);
                columns[i].chars = NULL;
            }
        }
        free(columns);
        columns = NULL;
    }
}

/* Initialize all columns */
static void init_columns(int lines, int cols) {
    num_lines = lines;
    num_cols = cols;

    free_columns();
    columns = (Column*)calloc(cols, sizeof(Column));

    for (int i = 0; i < cols; i++) {
        columns[i].chars = NULL;
        init_column(i);
    }
}

/* Get color pair for a column position */
static int get_color_pair(int is_head, int row) {
    if (opts.rainbow) {
        static const int rainbow_pairs[] = {
            PAIR_RED, PAIR_YELLOW, PAIR_GREEN, PAIR_CYAN, PAIR_BLUE, PAIR_MAGENTA, PAIR_WHITE
        };
        return rainbow_pairs[row % 7];
    }
    if (is_head) {
        return PAIR_WHITE;
    }
    return opts.color_pair;
}

/* Draw a single frame */
static void draw_frame(void) {
    for (int col = 0; col < num_cols; col++) {
        Column *c = &columns[col];

        /* Async mode: skip columns based on timer */
        if (opts.async_mode) {
            if (c->timer > 0) {
                c->timer--;
                continue;
            }
            c->timer = rand() % 4;
        }

        int pos = c->pos;
        int length = c->length;

        /* Draw head character (white/bright) */
        int head_row = pos;
        if (head_row >= 0 && head_row < num_lines) {
            char ch;
            if (opts.lambda) {
                ch = 'O';  /* Use 'O' as lambda placeholder */
            } else {
                ch = get_rand_char();
            }
            c->chars[head_row] = ch;

            int color = get_color_pair(1, head_row);
            int attr = (int)COLOR_PAIR(color);

            if (!opts.rainbow) {
                attr = (int)COLOR_PAIR(PAIR_WHITE);
            }
            if (opts.bold_all || (!opts.no_bold && !opts.shadow_only)) {
                attr |= A_BOLD;
            }
            if (opts.shadow_only) {
                attr = (int)COLOR_PAIR(opts.color_pair);
            }

            mvwaddch(stdscr, head_row, col, (chtype)(ch | attr));
        }

        /* Redraw previous head as body (green/color) */
        int body_row = pos - 1;
        if (body_row >= 0 && body_row < num_lines) {
            char ch = c->chars[body_row];
            if (ch == ' ' || ch == 0) {
                ch = get_rand_char();
                c->chars[body_row] = ch;
            }

            int color = get_color_pair(0, body_row);
            int attr = (int)COLOR_PAIR(color);

            if (opts.bold_all) {
                attr |= A_BOLD;
            } else if (opts.bold_some) {
                if (rand() % 2) attr |= A_BOLD;
            }
            if (opts.shadow_only) {
                attr = (int)COLOR_PAIR(opts.color_pair);
                ch = ' ';
            }

            mvwaddch(stdscr, body_row, col, (chtype)(ch | attr));
        }

        /* Erase tail */
        int tail_row = pos - length;
        if (tail_row >= 0 && tail_row < num_lines) {
            c->chars[tail_row] = ' ';
            mvwaddch(stdscr, tail_row, col, ' ');
        }

        /* Kinetic: randomly change characters in body */
        if (opts.kinetic) {
            int start = pos - length + 1;
            if (start < 0) start = 0;
            int end = pos;
            if (end > num_lines) end = num_lines;

            for (int row = start; row < end; row++) {
                if (rand() % 20 == 0) {  /* ~5% chance */
                    char ch = get_rand_char();
                    c->chars[row] = ch;
                    int color = get_color_pair(0, row);
                    int attr = (int)COLOR_PAIR(color);
                    if (opts.bold_all) attr |= A_BOLD;
                    else if (opts.bold_some && rand() % 2) attr |= A_BOLD;
                    mvwaddch(stdscr, row, col, (chtype)(ch | attr));
                }
            }
        }

        /* Advance position */
        c->pos++;

        /* Reset column when stream scrolls past screen */
        if (pos - length > num_lines) {
            if (c->space > 0) {
                c->space--;
            } else {
                c->length = 3 + rand() % (num_lines - 2);
                c->pos = 0;
                c->space = 1 + rand() % num_lines;
                memset(c->chars, ' ', num_lines);
            }
        }
    }
}

/* Draw message in center of screen */
static void draw_message(const char *msg) {
    if (!msg || !*msg) return;

    int len = strlen(msg);
    int row = num_lines / 2;
    int col = (num_cols - len) / 2;
    if (col < 0) col = 0;

    int attr = (int)COLOR_PAIR(PAIR_WHITE) | A_BOLD;

    wattron(stdscr, attr);
    mvwaddstr(stdscr, row, col, msg);
    wattroff(stdscr, attr);
}

static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void) {
    printf(" CMatrix version %s (compiled %s, %s)\n", CMATRIX_VERSION, COMPILED_TIME, COMPILED_DATE);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

int main(int argc, char *argv[]) {
    int opt;

    /* Initialize options */
    memset(&opts, 0, sizeof(opts));
    opts.no_bold = 1;  /* Default: no bold */
    opts.delay = 4;    /* Default delay */
    opts.color_pair = PAIR_GREEN;  /* Default color: green */
    opts.message = NULL;

    /* Parse arguments */
    while ((opt = getopt(argc, argv, "abBcfhLlonskrxmVu:C:M:t:?")) != -1) {
        switch (opt) {
            case 'a':
                opts.async_mode = 1;
                break;
            case 'b':
                opts.bold_some = 1;
                opts.bold_all = 0;
                opts.no_bold = 0;
                break;
            case 'B':
                opts.bold_all = 1;
                opts.bold_some = 0;
                opts.no_bold = 0;
                break;
            case 'c':
                opts.japanese = 1;
                break;
            case 'f':
                opts.force = 1;
                break;
            case 'h':
            case '?':
                print_usage();
                return 0;
            case 'l':
                opts.linux_mode = 1;
                break;
            case 'L':
                opts.locked = 1;
                break;
            case 'o':
                opts.old_style = 1;
                break;
            case 'n':
                opts.no_bold = 1;
                opts.bold_some = 0;
                opts.bold_all = 0;
                break;
            case 's':
                opts.screensaver = 1;
                break;
            case 'k':
                opts.kinetic = 1;
                break;
            case 'r':
                opts.rainbow = 1;
                break;
            case 'x':
                opts.xwindow = 1;
                break;
            case 'm':
                opts.lambda = 1;
                break;
            case 'V':
                print_version();
                return 0;
            case 'u': {
                int d = atoi(optarg);
                if (d < 0 || d > 10) {
                    fprintf(stderr, " Invalid delay value\n");
                    return 1;
                }
                opts.delay = d;
                break;
            }
            case 'C': {
                if (strcmp(optarg, "green") == 0) opts.color_pair = PAIR_GREEN;
                else if (strcmp(optarg, "red") == 0) opts.color_pair = PAIR_RED;
                else if (strcmp(optarg, "blue") == 0) opts.color_pair = PAIR_BLUE;
                else if (strcmp(optarg, "white") == 0) opts.color_pair = PAIR_WHITE;
                else if (strcmp(optarg, "yellow") == 0) opts.color_pair = PAIR_YELLOW;
                else if (strcmp(optarg, "cyan") == 0) opts.color_pair = PAIR_CYAN;
                else if (strcmp(optarg, "magenta") == 0) opts.color_pair = PAIR_MAGENTA;
                else if (strcmp(optarg, "black") == 0) opts.color_pair = PAIR_BLACK;
                else {
                    printf(" Invalid color selection\n");
                    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    return 1;
                }
                break;
            }
            case 'M':
                opts.message = optarg;
                break;
            case 't':
                opts.tty = optarg;
                break;
            default:
                print_usage();
                return 1;
        }
    }

    /* Setup signal handlers */
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);
    signal(SIGWINCH, handle_resize);

    /* Initialize ncurses */
    if (!initscr()) {
        fprintf(stderr, "Error initializing ncurses\n");
        return 1;
    }

    start_color();
    use_default_colors();

    /* Initialize color pairs */
    init_pair(PAIR_GREEN,   COLOR_GREEN,   -1);
    init_pair(PAIR_RED,     COLOR_RED,     -1);
    init_pair(PAIR_BLUE,    COLOR_BLUE,    -1);
    init_pair(PAIR_WHITE,   COLOR_WHITE,   -1);
    init_pair(PAIR_YELLOW,  COLOR_YELLOW,  -1);
    init_pair(PAIR_CYAN,    COLOR_CYAN,    -1);
    init_pair(PAIR_MAGENTA, COLOR_MAGENTA, -1);
    init_pair(PAIR_BLACK,   COLOR_BLACK,   -1);

    noecho();
    cbreak();
    curs_set(0);
    keypad(stdscr, 1);
    nodelay(stdscr, 1);

    /* Seed random number generator */
    srand((unsigned)time(NULL));

    /* Initialize columns */
    init_columns(LINES, COLS);

    /* Set message for lock mode */
    char *message = opts.message;
    static char lock_msg[] = "Computer locked. Press any key to unlock.";
    if (opts.locked && !message) {
        message = lock_msg;
    }

    /* Main loop */
    while (1) {
        /* Handle resize */
        if (need_resize) {
            need_resize = 0;
            endwin();
            refresh();
            init_columns(LINES, COLS);
            clear();
        }

        /* Draw frame */
        draw_frame();

        /* Draw message if any */
        if (message && *message) {
            draw_message(message);
        }

        refresh();

        /* Handle input */
        int ch = getch();

        if (ch == KEY_RESIZE) {
            endwin();
            refresh();
            init_columns(LINES, COLS);
            clear();
            continue;
        }

        /* Screensaver mode: exit on any keypress */
        if (opts.screensaver && ch != ERR) {
            break;
        }

        /* Normal mode: handle keystrokes */
        if (!opts.locked && !opts.screensaver) {
            if (ch == 'q' || ch == 'Q') {
                break;
            } else if (ch == 'a') {
                opts.async_mode = !opts.async_mode;
                if (opts.async_mode) {
                    for (int i = 0; i < num_cols; i++) {
                        columns[i].timer = rand() % 5;
                    }
                }
            } else if (ch == 'b') {
                opts.bold_some = 1;
                opts.bold_all = 0;
                opts.no_bold = 0;
            } else if (ch == 'B') {
                opts.bold_all = 1;
                opts.bold_some = 0;
                opts.no_bold = 0;
            } else if (ch == 'n') {
                opts.no_bold = 1;
                opts.bold_some = 0;
                opts.bold_all = 0;
            } else if (ch >= '0' && ch <= '9') {
                opts.delay = ch - '0';
            } else if (ch == '!') { opts.color_pair = PAIR_RED; }
            else if (ch == '@') { opts.color_pair = PAIR_GREEN; }
            else if (ch == '#') { opts.color_pair = PAIR_YELLOW; }
            else if (ch == '$') { opts.color_pair = PAIR_BLUE; }
            else if (ch == '%') { opts.color_pair = PAIR_MAGENTA; }
            else if (ch == '^') { opts.color_pair = PAIR_CYAN; }
            else if (ch == '&') { opts.color_pair = PAIR_WHITE; }
            else if (ch == ')') { opts.color_pair = PAIR_BLACK; }
        }

        /* Sleep based on delay: delay * 30000 microseconds */
        if (opts.delay > 0) {
            usleep(opts.delay * 30000);
        }
    }

    /* Cleanup */
    free_columns();
    endwin();

    return 0;
}
