 */
typedef struct {
    int length;     /* stream length (number of visible chars) */
    int head;       /* current head row position (can be negative = above screen) */
    int space;      /* remaining blank rows before next stream starts */
    int *chars;     /* character values for each screen row (LINES elements) */
    int timer;      /* async timer countdown */
