        memset(streams[i].chars, ' ', screen_rows * sizeof(int));
        for (int r = 0; r < screen_rows; r++) {
            streams[i].chars[r] = ' ';
        }
        init_stream(i);
    }
}

/* Get character attribute based on options */
static chtype get_attr(int color_pair, int force_bold) {
    chtype attr = COLOR_PAIR(color_pair);

    if (opts.bold_all || force_bold) {
        attr |= A_BOLD;
    } else if (opts.bold_some) {
        if (rand() % 2) attr |= A_BOLD;
    }

    return attr;
}

/* Get color pair for head vs body */
static int get_color(int is_head, int row) {
    if (opts.rainbow) {
        return rainbow_pairs[row % NUM_RAINBOW];
    }
    if (opts.shadow_only) {
        return opts.color_pair;
    }
    if (is_head) {
        return PAIR_WHITE;
    }
    return opts.color_pair;
}

/* Draw one frame of the animation */
static void draw_frame(void) {
    int lines = screen_rows;
    int cols = screen_cols;

    for (int i = 0; i < num_streams; i++) {
        ColStream *s = &streams[i];
        int col = i * 2;  /* Screen column (0, 2, 4, ...) */

        if (col >= cols) continue;

        /* Async mode: skip based on timer */
        if (opts.async_mode) {
            if (s->timer > 0) {
                s->timer--;
                continue;
            }
            s->timer = rand() % 4;
        }

        int head = s->head;
        int len = s->length;

        /* Draw head character */
        if (head >= 0 && head < lines) {
            int ch = get_rand_char();
            s->chars[head] = ch;

            int cp = get_color(1, head);
            chtype attr = get_attr(cp, 0);

            if (opts.shadow_only) {
                mvwaddch(stdscr, head, col, (chtype)(' ' | attr));
            } else {
                /* Head is always white+bold by default */
                chtype head_attr = COLOR_PAIR(PAIR_WHITE);
                if (opts.bold_all || (!opts.no_bold)) {
                    /* Don't force bold for head in no-bold mode */
                }
                if (opts.rainbow) {
                    head_attr = COLOR_PAIR(cp);
                }
                mvwaddch(stdscr, head, col, (chtype)(ch | head_attr));
            }
        }

        /* Redraw previous head position as body (in stream color) */
        int body = head - 1;
        if (body >= 0 && body < lines) {
            int ch = s->chars[body];
            if (ch == ' ' || ch == 0) {
                ch = get_rand_char();
                s->chars[body] = ch;
            }

            int cp = get_color(0, body);
            chtype attr = get_attr(cp, 0);

            if (opts.shadow_only) {
                mvwaddch(stdscr, body, col, (chtype)(' ' | attr));
            } else if (opts.kinetic) {
                /* Kinetic: randomly change body chars */
                if (rand() % 20 == 0) {
                    ch = get_rand_char();
                    s->chars[body] = ch;
                }
                mvwaddch(stdscr, body, col, (chtype)(ch | attr));
            } else {
                mvwaddch(stdscr, body, col, (chtype)(ch | attr));
            }
        }

        /* Erase tail */
        int tail = head - len;
        if (tail >= 0 && tail < lines) {
            s->chars[tail] = ' ';
            /* Erase using background color (green) */
            chtype bg_attr = COLOR_PAIR(opts.color_pair);
            mvwaddch(stdscr, tail, col, (chtype)(' ' | bg_attr));
        }

        /* Advance head position */
        s->head++;

        /* Reset stream when it scrolls off screen */
        if (head - len > lines) {
            if (s->space > 0) {
                s->space--;
            } else {
                /* Start new stream */
                s->length = 3 + rand() % (lines > 3 ? lines - 3 : 1);
                s->head = 0;
                s->space = 1 + rand() % lines;
                for (int r = 0; r < lines; r++) {
                    s->chars[r] = ' ';
                }
            }
        }
    }
}

/* Draw message in center of screen */
static void draw_message(const char *msg) {
    if (!msg || !*msg) return;

    int len = strlen(msg);
    int row = screen_rows / 2;
    int col = (screen_cols - len) / 2;
    if (col < 0) col = 0;
    if (row < 0) row = 0;

    chtype attr = COLOR_PAIR(PAIR_WHITE) | A_BOLD;
    wattron(stdscr, (int)attr);
    mvwaddstr(stdscr, row, col, msg);
    wattroff(stdscr, (int)attr);
}

static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void) {
    printf(" CMatrix version %s (compiled %s, %s)\n", CMATRIX_VERSION, COMPILED_TIME, COMPILED_DATE);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

int main(int argc, char *argv[]) {
    int opt;

    /* Initialize options with defaults */
    memset(&opts, 0, sizeof(opts));
    opts.no_bold = 1;      /* Default: no bold */
    opts.delay = 4;        /* Default delay */
    opts.color_pair = PAIR_GREEN;  /* Default color: green */

    /* Parse command line arguments */
    while ((opt = getopt(argc, argv, "abBcfhLlonskrxmVu:C:M:t:?")) != -1) {
        switch (opt) {
            case 'a':
                opts.async_mode = 1;
                break;
            case 'b':
                opts.bold_some = 1;
                opts.bold_all = 0;
                opts.no_bold = 0;
                break;
            case 'B':
                opts.bold_all = 1;
                opts.bold_some = 0;
                opts.no_bold = 0;
                break;
            case 'c':
                opts.japanese = 1;
                break;
            case 'f':
                opts.force = 1;
                break;
            case 'h':
            case '?':
                print_usage();
                return 0;
            case 'l':
                opts.linux_mode = 1;
                break;
            case 'L':
                opts.locked = 1;
                break;
            case 'o':
                opts.old_style = 1;
                break;
            case 'n':
                opts.no_bold = 1;
                opts.bold_some = 0;
                opts.bold_all = 0;
                break;
            case 's':
                opts.screensaver = 1;
                break;
            case 'k':
                opts.kinetic = 1;
                break;
            case 'r':
                opts.rainbow = 1;
                break;
            case 'x':
                opts.xwindow = 1;
                break;
            case 'm':
                opts.lambda = 1;
                break;
            case 'V':
                print_version();
                return 0;
            case 'u': {
                int d = atoi(optarg);
                if (d < 0 || d > 10) {
                    fprintf(stderr, " Invalid delay value\n");
                    return 1;
                }
                opts.delay = d;
                break;
            }
            case 'C': {
                const char *colors[] = {
                    "green", "red", "blue", "white", "yellow", "cyan", "magenta", "black"
                };
                const int pairs[] = {
                    PAIR_GREEN, PAIR_RED, PAIR_BLUE, PAIR_WHITE,
                    PAIR_YELLOW, PAIR_CYAN, PAIR_MAGENTA, PAIR_BLACK
                };
                int found = 0;
                for (int n = 0; n < 8; n++) {
                    if (strcmp(optarg, colors[n]) == 0) {
                        opts.color_pair = pairs[n];
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    printf(" Invalid color selection\n");
                    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    return 1;
                }
                break;
            }
            case 'M':
                opts.message = optarg;
                break;
            case 't':
                opts.tty = optarg;
                break;
            default:
                print_usage();
                return 1;
        }
    }

    /* Setup signal handlers */
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);
    signal(SIGWINCH, handle_sigwinch);

    /* Initialize ncurses */
    if (!initscr()) {
        fprintf(stderr, "Error initializing ncurses\n");
        return 1;
    }

    start_color();
    use_default_colors();

    /* Initialize color pairs */
    init_pair(PAIR_GREEN,   COLOR_GREEN,   -1);
    init_pair(PAIR_RED,     COLOR_RED,     -1);
    init_pair(PAIR_BLUE,    COLOR_BLUE,    -1);
    init_pair(PAIR_WHITE,   COLOR_WHITE,   -1);
    init_pair(PAIR_YELLOW,  COLOR_YELLOW,  -1);
    init_pair(PAIR_CYAN,    COLOR_CYAN,    -1);
    init_pair(PAIR_MAGENTA, COLOR_MAGENTA, -1);
    init_pair(PAIR_BLACK,   COLOR_BLACK,   -1);

    noecho();
    cbreak();
    curs_set(0);
    keypad(stdscr, TRUE);
    nodelay(stdscr, TRUE);

    /* Set background to main color */
    bkgd(COLOR_PAIR(opts.color_pair) | ' ');

    /* Clear screen (fills with background color) */
    clear();

    /* Seed random number generator */
    srand((unsigned)time(NULL));

    /* Initialize streams */
    init_streams();

    /* Determine message to display */
    char *message = opts.message;
    static const char lock_msg[] = "Computer locked. Press any key to unlock.";
    if (opts.locked && !message) {
        message = (char*)lock_msg;
    }

    /* Main animation loop */
    while (1) {
        /* Handle terminal resize */
        if (need_resize) {
            need_resize = 0;
            endwin();
            refresh();
            bkgd(COLOR_PAIR(opts.color_pair) | ' ');
            clear();
            init_streams();
        }

        /* Draw one frame */
        draw_frame();

        /* Draw message overlay */
        if (message && *message) {
            draw_message(message);
        }

        /* Refresh display */
        refresh();

        /* Handle keyboard input */
        int ch = getch();

        if (ch == KEY_RESIZE) {
            endwin();
            refresh();
            bkgd(COLOR_PAIR(opts.color_pair) | ' ');
            clear();
            init_streams();
            continue;
        }

        /* Screensaver mode: exit on any keypress */
        if (opts.screensaver && ch != ERR) {
            break;
        }

        /* Interactive key handling (not in locked/screensaver mode) */
        if (!opts.locked && !opts.screensaver) {
            switch (ch) {
                case 'q':
                case 'Q':
                    goto cleanup;

                case 'a':
                    opts.async_mode = !opts.async_mode;
                    if (opts.async_mode) {
                        for (int i = 0; i < num_streams; i++) {
                            streams[i].timer = rand() % 5;
                        }
                    }
                    break;

                case 'b':
                    opts.bold_some = 1;
                    opts.bold_all = 0;
                    opts.no_bold = 0;
                    break;

                case 'B':
                    opts.bold_all = 1;
                    opts.bold_some = 0;
                    opts.no_bold = 0;
                    break;

                case 'n':
                    opts.no_bold = 1;
                    opts.bold_some = 0;
                    opts.bold_all = 0;
                    break;

                case '0': case '1': case '2': case '3': case '4':
                case '5': case '6': case '7': case '8': case '9':
                    opts.delay = ch - '0';
                    break;

                case '!': opts.color_pair = PAIR_RED;     break;
                case '@': opts.color_pair = PAIR_GREEN;   break;
                case '#': opts.color_pair = PAIR_YELLOW;  break;
                case '$': opts.color_pair = PAIR_BLUE;    break;
                case '%': opts.color_pair = PAIR_MAGENTA; break;
                case '^': opts.color_pair = PAIR_CYAN;    break;
                case '&': opts.color_pair = PAIR_WHITE;   break;
                case ')': opts.color_pair = PAIR_BLACK;   break;
            }
        }

        /* Frame delay: delay * 30000 microseconds */
        if (opts.delay > 0) {
            usleep(opts.delay * 30000);
        }
    }

cleanup:
    free_streams();
    endwin();
    return 0;
}
