    memset(&opts, 0, sizeof(opts));
    opts.no_bold   = 1;          /* Default: no bold */
    opts.delay     = 4;          /* Default delay */
    opts.color_pair = PAIR_GREEN; /* Default color: green */

    /* Parse arguments */
    while ((opt = getopt(argc, argv, "abBcfhLlonskrxmVu:C:M:t:?")) != -1) {
        switch (opt) {
            case 'a':
                opts.async_mode = 1;
                break;
            case 'b':
                opts.bold_some = 1;
                opts.bold_all  = 0;
                opts.no_bold   = 0;
                break;
            case 'B':
                opts.bold_all  = 1;
                opts.bold_some = 0;
                opts.no_bold   = 0;
                break;
            case 'c':
                opts.japanese = 1;
                break;
            case 'f':
                opts.force = 1;
                break;
            case 'h':
            case '?':
                print_usage();
                return 0;
            case 'l':
                opts.linux_mode = 1;
                break;
            case 'L':
                opts.locked = 1;
                break;
            case 'o':
                opts.old_style = 1;
                break;
            case 'n':
