            case 'r':
                opts.rainbow = 1;
                break;
            case 'x':
                opts.xwindow = 1;
                break;
            case 'm':
                opts.lambda = 1;
                break;
            case 'V':
                print_version();
                return 0;
            case 'u': {
                int d = atoi(optarg);
                if (d < 0 || d > 10) {
                    fprintf(stderr, " Invalid delay value\n");
                    return 1;
                }
                opts.delay = d;
                break;
            }
            case 'C': {
                /* Color selection */
                struct { const char *name; int pair; } colors[] = {
                    {"green",   PAIR_GREEN},
                    {"red",     PAIR_RED},
                    {"blue",    PAIR_BLUE},
                    {"white",   PAIR_WHITE},
                    {"yellow",  PAIR_YELLOW},
                    {"cyan",    PAIR_CYAN},
                    {"magenta", PAIR_MAGENTA},
                    {"black",   PAIR_BLACK},
                };
                int found = 0;
                for (int n = 0; n < 8; n++) {
                    if (strcmp(optarg, colors[n].name) == 0) {
                        opts.color_pair = colors[n].pair;
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    printf(" Invalid color selection\n");
                    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    return 1;
                }
                break;
            }
            case 'M':
                opts.message = optarg;
                break;
            case 't':
                opts.tty = optarg;
                break;
            default:
                print_usage();
                return 1;
