        return (int)'O';
    }
    return CHAR_MIN + (rand() % CHAR_COUNT);
}

/* ========================================================
 * Stream management
 * ======================================================== */
static void init_stream(ColStream *s, int lines) {
    s->length = 3 + rand() % (lines > 3 ? lines - 3 : 1);
    s->head   = -(rand() % lines);  /* Start above screen: 0 to -(lines-1) */
    s->space  = 1 + rand() % lines;
    s->timer  = opts.async_mode ? rand() % 5 : 0;

    if (s->chars) {
        for (int i = 0; i < lines; i++) {
            s->chars[i] = ' ';
        }
    }
}

static void free_streams(void) {
