    screen_rows = LINES;
    screen_cols = COLS;

    /* Use every other column */
    num_streams = COLS / 2;
    if (num_streams < 1) num_streams = 1;

    streams = (ColStream *)calloc(num_streams, sizeof(ColStream));
    if (!streams) {
        endwin();
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    for (int i = 0; i < num_streams; i++) {
        streams[i].chars = (int *)malloc(screen_rows * sizeof(int));
        if (!streams[i].chars) {
            endwin();
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        for (int r = 0; r < screen_rows; r++) {
            streams[i].chars[r] = ' ';
        }
        init_stream(&streams[i], screen_rows);
    }
}

/* ========================================================
 * Animation
 * ======================================================== */
static void draw_frame(void) {
    int lines = screen_rows;
    int cols  = screen_cols;

    for (int i = 0; i < num_streams; i++) {
        ColStream *s   = &streams[i];
        int        col = i * 2;  /* Screen column: 0, 2, 4, ... */

        if (col >= cols) continue;

        /* Async mode: skip this column if timer > 0 */
        if (opts.async_mode) {
            if (s->timer > 0) {
                s->timer--;
                continue;
            }
            s->timer = rand() % 4;
        }

        int pos = s->head;
        int len = s->length;

        /* --- Draw head (at current position) --- */
        if (pos >= 0 && pos < lines) {
            int ch = get_rand_char();
            s->chars[pos] = ch;

            chtype attr;
            if (opts.shadow_only) {
                /* Shadow: just background color space */
                attr = (chtype)(' ' | COLOR_PAIR(opts.color_pair));
            } else if (opts.rainbow) {
                int cp = rainbow_pairs[pos % NUM_RAINBOW];
                attr = (chtype)(ch | COLOR_PAIR(cp));
                if (opts.bold_all) attr |= A_BOLD;
                else if (opts.bold_some && (rand() % 2)) attr |= A_BOLD;
            } else {
                /* Head is white by default */
                attr = (chtype)(ch | COLOR_PAIR(PAIR_WHITE));
                if (opts.bold_all) attr |= A_BOLD;
                else if (opts.bold_some && (rand() % 2)) attr |= A_BOLD;
                /* -n (no bold) = neither bold_all nor bold_some, so no A_BOLD */
            }
            mvwaddch(stdscr, pos, col, attr);
        }

        /* --- Redraw previous head as body (one row up) --- */
        int body = pos - 1;
        if (body >= 0 && body < lines) {
            int ch = s->chars[body];
            if (ch == ' ' || ch == 0) {
                ch = get_rand_char();
                s->chars[body] = ch;
            }

            /* Kinetic: randomly change body char */
            if (opts.kinetic && (rand() % 20 == 0)) {
                ch = get_rand_char();
                s->chars[body] = ch;
            }

            chtype attr;
            if (opts.shadow_only) {
                attr = (chtype)(' ' | COLOR_PAIR(opts.color_pair));
            } else if (opts.rainbow) {
                int cp = rainbow_pairs[body % NUM_RAINBOW];
                attr = (chtype)(ch | COLOR_PAIR(cp));
                if (opts.bold_all) attr |= A_BOLD;
                else if (opts.bold_some && (rand() % 2)) attr |= A_BOLD;
            } else {
                attr = (chtype)(ch | COLOR_PAIR(opts.color_pair));
                if (opts.bold_all) attr |= A_BOLD;
                else if (opts.bold_some && (rand() % 2)) attr |= A_BOLD;
            }
            mvwaddch(stdscr, body, col, attr);
        }

        /* --- Erase tail --- */
        int tail = pos - len;
        if (tail >= 0 && tail < lines) {
            s->chars[tail] = ' ';
            /* Write a plain space (uses background attrs) */
            mvwaddch(stdscr, tail, col, (chtype)(' '));
        }

        /* Advance head */
        s->head++;

        /* Reset stream if it has scrolled completely off screen */
        if (pos - len > lines) {
            if (s->space > 0) {
                s->space--;
            } else {
                s->length = 3 + rand() % (lines > 3 ? lines - 3 : 1);
                s->head   = 0;
                s->space  = 1 + rand() % lines;
                for (int r = 0; r < lines; r++) {
                    s->chars[r] = ' ';
                }
            }
        }
    }
}

/* Draw centered message */
static void draw_message(const char *msg) {
    if (!msg || !*msg) return;

    int len = (int)strlen(msg);
    int row = screen_rows / 2;
    int col = (screen_cols - len) / 2;
    if (col < 0) col = 0;
    if (row < 0) row = 0;

    /* White bold message */
    chtype attr = COLOR_PAIR(PAIR_WHITE) | A_BOLD;
    wattron(stdscr, (int)attr);
    mvwaddstr(stdscr, row, col, msg);
    wattroff(stdscr, (int)attr);
}

/* ========================================================
 * Help / version
 * ======================================================== */
static void print_usage(void) {
    puts(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]");
    puts(" -a: Asynchronous scroll");
    puts(" -b: Bold characters on");
    puts(" -B: All bold characters (overrides -b)");
    puts(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts");
    puts(" -f: Force the linux $TERM type to be on");
    puts(" -l: Linux mode (uses matrix console font)");
    puts(" -L: Lock mode (can be closed from another terminal)");
    puts(" -o: Use old-style scrolling");
    puts(" -h: Print usage and exit");
    puts(" -n: No bold characters (overrides -b and -B, default)");
    puts(" -s: \"Screensaver\" mode, exits on first keystroke");
    puts(" -x: X window mode, use if your xterm is using mtx.pcf");
    puts(" -V: Print version information and exit");
    puts(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.");
    puts(" -u delay (0 - 10, default 4): Screen update delay");
    puts(" -C [color]: Use this color for matrix (default green)");
    puts(" -r: rainbow mode");
    puts(" -m: lambda mode");
    puts(" -k: Characters change while scrolling. (Works without -o opt.)");
    puts(" -t [tty]: Set tty to use");
}

static void print_version(void) {
    printf(" CMatrix version %s (compiled %s, %s)\n",
           CMATRIX_VERSION, COMPILED_TIME, COMPILED_DATE);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

/* ========================================================
 * Main
 * ======================================================== */
int main(int argc, char *argv[]) {
    int opt;

    /* Default options */
    memset(&opts, 0, sizeof(opts));
    opts.no_bold   = 1;          /* Default: no bold */
    opts.delay     = 4;          /* Default delay */
    opts.color_pair = PAIR_GREEN; /* Default color: green */

    /* Parse arguments */
    while ((opt = getopt(argc, argv, "abBcfhLlonskrxmVu:C:M:t:?")) != -1) {
        switch (opt) {
            case 'a':
                opts.async_mode = 1;
                break;
            case 'b':
                opts.bold_some = 1;
                opts.bold_all  = 0;
                opts.no_bold   = 0;
                break;
            case 'B':
                opts.bold_all  = 1;
                opts.bold_some = 0;
                opts.no_bold   = 0;
                break;
            case 'c':
                opts.japanese = 1;
                break;
            case 'f':
                opts.force = 1;
                break;
            case 'h':
            case '?':
                print_usage();
                return 0;
            case 'l':
                opts.linux_mode = 1;
                break;
            case 'L':
                opts.locked = 1;
                break;
            case 'o':
                opts.old_style = 1;
                break;
            case 'n':
                opts.no_bold   = 1;
                opts.bold_some = 0;
                opts.bold_all  = 0;
                break;
            case 's':
                opts.screensaver = 1;
                break;
            case 'k':
                opts.kinetic = 1;
                break;
            case 'r':
                opts.rainbow = 1;
                break;
            case 'x':
                opts.xwindow = 1;
                break;
            case 'm':
                opts.lambda = 1;
                break;
            case 'V':
                print_version();
                return 0;
            case 'u': {
                int d = atoi(optarg);
                if (d < 0 || d > 10) {
                    fprintf(stderr, " Invalid delay value\n");
                    return 1;
                }
                opts.delay = d;
                break;
            }
            case 'C': {
                /* Color selection */
                struct { const char *name; int pair; } colors[] = {
                    {"green",   PAIR_GREEN},
                    {"red",     PAIR_RED},
                    {"blue",    PAIR_BLUE},
                    {"white",   PAIR_WHITE},
                    {"yellow",  PAIR_YELLOW},
                    {"cyan",    PAIR_CYAN},
                    {"magenta", PAIR_MAGENTA},
                    {"black",   PAIR_BLACK},
                };
                int found = 0;
                for (int n = 0; n < 8; n++) {
                    if (strcmp(optarg, colors[n].name) == 0) {
                        opts.color_pair = colors[n].pair;
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    printf(" Invalid color selection\n");
                    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    return 1;
                }
                break;
            }
            case 'M':
                opts.message = optarg;
                break;
            case 't':
                opts.tty = optarg;
                break;
            default:
                print_usage();
                return 1;
        }
    }

    /* Setup signals */
    signal(SIGINT,  handle_sigint);
    signal(SIGTERM, handle_sigint);
    signal(SIGWINCH, handle_sigwinch);

    /* Initialize ncurses */
    if (!initscr()) {
        fprintf(stderr, "Error initializing ncurses\n");
        return 1;
    }

    start_color();
    use_default_colors();

    /* Setup color pairs: (pair_num, fg_color, bg_color) */
    init_pair(PAIR_GREEN,   COLOR_GREEN,   -1);
    init_pair(PAIR_RED,     COLOR_RED,     -1);
    init_pair(PAIR_BLUE,    COLOR_BLUE,    -1);
    init_pair(PAIR_WHITE,   COLOR_WHITE,   -1);
    init_pair(PAIR_YELLOW,  COLOR_YELLOW,  -1);
    init_pair(PAIR_CYAN,    COLOR_CYAN,    -1);
    init_pair(PAIR_MAGENTA, COLOR_MAGENTA, -1);
    init_pair(PAIR_BLACK,   COLOR_BLACK,   -1);

    noecho();
    cbreak();
    curs_set(0);
    keypad(stdscr, TRUE);
    nodelay(stdscr, TRUE);

    /* Set background to main color */
    bkgd(COLOR_PAIR(opts.color_pair) | (chtype)' ');
    clear();

    /* Seed random number generator */
    srand((unsigned int)time(NULL));

    /* Initialize animation */
    init_streams();

    /* Message setup */
    char *message = opts.message;
    static const char lock_msg[] = "Computer locked. Press any key to unlock.";
    if (opts.locked && !message) {
        message = (char *)lock_msg;
    }

    /* ---- Main animation loop ---- */
    while (1) {
        /* Handle terminal resize */
        if (need_resize) {
            need_resize = 0;
            endwin();
            refresh();
            bkgd(COLOR_PAIR(opts.color_pair) | (chtype)' ');
            clear();
            init_streams();
        }

        /* Render one frame */
        draw_frame();

        /* Draw message overlay */
        if (message && *message) {
            draw_message(message);
        }

        /* Flush to screen */
        refresh();

        /* Handle keyboard */
        int ch = getch();

        if (ch == KEY_RESIZE) {
            endwin();
            refresh();
            bkgd(COLOR_PAIR(opts.color_pair) | (chtype)' ');
            clear();
            init_streams();
            continue;
        }

        /* Screensaver: exit on any key */
        if (opts.screensaver && ch != ERR) {
            break;
        }

        /* Interactive keystrokes (not in locked/screensaver mode) */
        if (!opts.locked && !opts.screensaver) {
            switch (ch) {
                case 'q':
                case 'Q':
                    goto done;

                case 'a':
                    opts.async_mode = !opts.async_mode;
                    if (opts.async_mode) {
                        for (int i = 0; i < num_streams; i++) {
                            streams[i].timer = rand() % 5;
                        }
                    }
                    break;

                case 'b':
                    opts.bold_some = 1;
                    opts.bold_all  = 0;
                    opts.no_bold   = 0;
                    break;

                case 'B':
                    opts.bold_all  = 1;
                    opts.bold_some = 0;
                    opts.no_bold   = 0;
                    break;

                case 'n':
                    opts.no_bold   = 1;
                    opts.bold_some = 0;
                    opts.bold_all  = 0;
                    break;

                case '0': case '1': case '2': case '3': case '4':
                case '5': case '6': case '7': case '8': case '9':
                    opts.delay = ch - '0';
                    break;

                /* Color change keys */
                case '!': opts.color_pair = PAIR_RED;     break;
                case '@': opts.color_pair = PAIR_GREEN;   break;
                case '#': opts.color_pair = PAIR_YELLOW;  break;
                case '$': opts.color_pair = PAIR_BLUE;    break;
                case '%': opts.color_pair = PAIR_MAGENTA; break;
                case '^': opts.color_pair = PAIR_CYAN;    break;
                case '&': opts.color_pair = PAIR_WHITE;   break;
                case ')': opts.color_pair = PAIR_BLACK;   break;
            }
        }

        /* Frame delay: delay * 10000 microseconds */
        if (opts.delay > 0) {
            usleep(opts.delay * 10000);
        }
    }

done:
    free_streams();
    endwin();
    return 0;
}
